import { tags } from "typia";

/**
 * Single policy violation record for a member. Tracks when violations occurred,
 * violation type, and context. Used for cumulative violation counting toward
 * automatic enforcement thresholds and for historical violation analysis.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IDiscussionBoardUserViolation = {
  /**
   * Unique identifier for this violation record. System-generated UUID
   * primary key. Used for referencing violation in moderation logs.
   */
  id: string & tags.Format<"uuid">;

  /**
   * Category or type of violation committed. Valid values include: 'spam'
   * (repetitive/promotional content), 'harassment' (targeted attacks),
   * 'inappropriate_content' (graphic/offensive material), 'off_topic'
   * (content unrelated to economics/politics), 'misinformation' (false claims
   * presented as fact), 'copyright_violation' (unauthorized content
   * reproduction), 'illegal_content' (content promoting illegal activities).
   * Enables categorization and pattern analysis.
   */
  violation_type: string;

  /**
   * Brief description of the specific violation. Explains what policy was
   * violated and provides context. Supports compliance documentation and user
   * communication about enforcement.
   */
  reason?: string | null | undefined;

  /**
   * Timestamp when the violation occurred (when user committed the policy
   * violation). Stored in ISO 8601 UTC format. Critical for calculating
   * 30-day and 90-day violation windows that trigger automatic suspension (3+
   * violations) and banning (5+ violations).
   */
  violation_date: string & tags.Format<"date-time">;

  /**
   * Timestamp when this violation record was created in the system. May
   * differ from violation_date if violation is recorded after the fact. Used
   * for audit trail tracking.
   */
  created_at: string & tags.Format<"date-time">;
};
